// ── read_crop ────────────────────────────────────────────────────────
test("read_crop: video + bbox -> pixel crop + details", async () => {
	const { tools } = await makeTools({});
	const r = await tools.read_crop({ path: testVideo(), time_s: 0.5, bbox: [200, 200, 600, 600] });
	assert.equal(countImages(r.content), 1);
	assert.deepEqual(r.details.pixels, [64, 48, 192, 144]); // /1000 * [320,240]
	assert.deepEqual(r.details.source, [320, 240]);
	assert.ok(textBlocks(r.content).includes("128×96px of 320×240"), textBlocks(r.content));
});

