// ── semantic_crop ────────────────────────────────────────────────────
const SINGLE_CAND = {
	width: 320, height: 240,
	candidates: [{ id: 1, bbox: [100, 50, 200, 150], score: 0.9, phrase: "the ball" }],
	annotated_b64: "cmVjZWlwdA==",
};

const TWO_CAND = {
	width: 320, height: 240,
	candidates: [
		{ id: 1, bbox: [0, 0, 40, 40], score: 0.5, phrase: "a box" },
		{ id: 2, bbox: [100, 50, 200, 150], score: 0.4, phrase: "the ball" },
	],
	annotated_b64: "cmVjZWlwdA==",
};

test("semantic_crop: single candidate -> no selection subcall, receipt + crop", async () => {
	const { tools, stub } = await makeTools({ ground: () => SINGLE_CAND });
	const r = await tools.semantic_crop({ path: testImage(), target: "the ball" });
	assert.equal(countImages(r.content), 2); // receipt + crop
	assert.equal(r.details.selection_mode, "single");
	assert.equal(r.details.grounding_bbox.join(","), "100,50,200,150");
	assert.deepEqual(r.details.crop_bbox, [40, 0, 260, 220]); // S2.8 context ROI
	assert.equal(r.details.frame_size.join(","), "320,240");
	// no candidate-selection chat call
	assert.ok(!stub.calls.some((c) => c.url.includes("/chat/completions")),
		"single candidate must skip the VLM selection subcall");
});

test("semantic_crop: multiple candidates -> VLM selection subcall picks #2", async () => {
	let selectPrompt = null;
	const { tools, stub } = await makeTools({
		ground: () => TWO_CAND,
		select: (messages) => {
			selectPrompt = messages.flatMap((m) =>
				Array.isArray(m.content) ? m.content.filter((b) => b.type === "text").map((b) => b.text) : [])
				.join(" ");
			return "2";
		},
	});
	const r = await tools.semantic_crop({ path: testImage(), target: "the ball" });
	assert.equal(r.details.selection_mode, "vlm_select");
	assert.equal(r.details.grounding_bbox.join(","), "100,50,200,150");
	assert.ok(selectPrompt.includes("the ball"), `selection prompt should carry target: ${selectPrompt}`);
	assert.ok(selectPrompt.includes("1, 2"));
	const ground = stub.calls.find((c) => c.url.includes("/ground"));
	assert.equal(ground.body.topk, 6);
});

