// ── Thinking-model subcall replies (content null / reasoning present) ──
test("index_video: caption content+reasoning -> timeline from content, thinking in its own labeled block", async () => {
	const { tools } = await makeTools({
		caption: () => ({ content: "t=0.00s: nothing\n", reasoning: "let me examine the frames" }),
	});
	const r = await tools.index_video({ path: testVideo() });
	const txt = textBlocks(r.content);
	assert.ok(txt.includes("semantic timeline"), txt);
	assert.ok(txt.includes("t=0.00s: nothing"), txt);
	assert.ok(txt.includes("[caption subcall thinking]\nlet me examine the frames"), txt);
	// the reasoning must not leak into the timeline body itself
	const before = txt.split("[caption subcall thinking]")[0];
	assert.ok(!before.includes("let me examine"), "reasoning must stay in its labeled block");
});

test("index_video: caption content null (thinking-only reply) -> friendly error, no crash", async () => {
	const { tools } = await makeTools({
		caption: () => ({ content: null, reasoning: "thinking only, never committed an answer" }),
	});
	const r = await tools.index_video({ path: testVideo() });
	const txt = textBlocks(r.content);
	assert.equal(countImages(r.content), 0);
	assert.ok(txt.includes("no answer text"), txt);
	assert.ok(!txt.includes("Cannot read properties"), "must not surface the JS null-deref crash");
	assert.ok(txt.includes("[caption subcall thinking]\nthinking only"), txt);
	assert.equal(r.details.caption_ok, false);
});

test("semantic_crop: selection subcall gets enough tokens for a thinking model (>=128)", async () => {
	const { tools, stub } = await makeTools({ ground: () => TWO_CAND, select: () => "2" });
	await tools.semantic_crop({ path: testImage(), target: "the ball" });
	const sel = stub.calls.find((c) => c.url.includes("/chat/completions"));
	assert.ok(sel.body.max_tokens >= 128, `max_tokens=${sel.body.max_tokens} starves the thinking model`);
});

test("DeepSeek observer subcalls explicitly disable thinking", async () => {
	const { tools, stub } = await makeTools({
		caption: () => "t=0.00s: nothing\n",
		ground: () => TWO_CAND,
		select: () => "2",
	}, "https://api.deepseek.com");
	await tools.index_video({ path: testVideo() });
	await tools.semantic_crop({ path: testImage(), target: "the ball" });
	const calls = stub.calls.filter((c) => c.url.includes("/chat/completions"));
	assert.equal(calls.length, 2);
	for (const call of calls) {
		assert.deepEqual(call.body.thinking, { type: "disabled" });
	}
});

test("OpenRouter observer subcalls keep their existing request shape", async () => {
	const { tools, stub } = await makeTools({
		caption: () => "t=0.00s: nothing\n",
	}, "https://openrouter.ai/api/v1");
	await tools.index_video({ path: testVideo() });
	const call = stub.calls.find((c) => c.url.includes("/chat/completions"));
	assert.ok(call.url.startsWith("https://openrouter.ai/api/v1/"));
	assert.equal(call.body.thinking, undefined,
		"OpenRouter must not receive the DeepSeek-specific thinking field");
});

test("semantic_crop: selection content null (thinking-only reply) -> friendly error, no crash, no silent pick", async () => {
	const { tools } = await makeTools({
		ground: () => TWO_CAND,
		select: () => ({ content: null, reasoning: "deliberating but not committing" }),
	});
	const r = await tools.semantic_crop({ path: testImage(), target: "the ball" });
	const txt = textBlocks(r.content);
	assert.equal(countImages(r.content), 0, "no receipt/crop when selection failed");
	assert.ok(txt.includes("no answer text"), txt);
	assert.ok(!txt.includes("Cannot read properties"), "must not surface the JS null-deref crash");
	assert.ok(txt.includes("[selection subcall thinking]\ndeliberating"), txt);
	assert.equal(r.details.selection_mode, "vlm_select_failed");
});

test("semantic_crop: selection content+reasoning -> picks id from content, thinking labeled", async () => {
	const { tools } = await makeTools({
		ground: () => TWO_CAND,
		select: () => ({ content: "2", reasoning: "candidate 2 matches the ball" }),
	});
	const r = await tools.semantic_crop({ path: testImage(), target: "the ball" });
	assert.equal(r.details.grounding_bbox.join(","), "100,50,200,150"); // id 2
	assert.equal(r.details.selection_mode, "vlm_select");
	assert.ok(textBlocks(r.content).includes("[selection subcall thinking]\ncandidate 2 matches the ball"));
});

test("semantic_crop: select mentions several candidates -> last in-ids wins", async () => {
	const { tools } = await makeTools({ ground: () => TWO_CAND, select: () => "candidate 1 or 2" });
	const r = await tools.semantic_crop({ path: testImage(), target: "the ball" });
	assert.equal(r.details.grounding_bbox.join(","), "100,50,200,150"); // id 2 (last mentioned)
});

test("semantic_crop: select replies a number outside ids -> falls back to first candidate", async () => {
	const { tools } = await makeTools({ ground: () => TWO_CAND, select: () => "5" });
	const r = await tools.semantic_crop({ path: testImage(), target: "the ball" });
	assert.equal(r.details.grounding_bbox.join(","), "0,0,40,40"); // id 1
});
